"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { Text, Badge } from "@whop/react/components";
import { 
	ArrowRightIcon
} from "@radix-ui/react-icons";

export default function HomePage() {
	const [channelUrl, setChannelUrl] = useState("");
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [analysisResult, setAnalysisResult] = useState<any>(null);
	const [analysisData, setAnalysisData] = useState<any>(null);
	const [analysisReady, setAnalysisReady] = useState(false);
	const [activeTab, setActiveTab] = useState<string>("Channel DNA");

	const handleAnalyze = async () => {
		if (!channelUrl.trim()) {
			setError("Please enter a channel URL or username.");
			return;
		}
		setError(null);
		setLoading(true);
		setAnalysisReady(false);
		setAnalysisResult(null);
		setAnalysisData(null);
		try {
			const res = await fetch("/api/channel-analyze", {
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body: JSON.stringify({ channelUrl: channelUrl.trim() }),
			});
			if (!res.ok) {
				const errData = await res.json().catch(() => ({}));
				throw new Error(errData.error || "Analysis failed. Please try again.");
			}
			const data = await res.json();
			setAnalysisResult(data.analysis || null);
			setAnalysisData(data.data || null);
			setAnalysisReady(true);
		} catch (err) {
			setError(err instanceof Error ? err.message : "Analysis failed. Please try again.");
		} finally {
			setLoading(false);
		}
	};


	return (
		<div className="relative min-h-screen overflow-hidden bg-[#05000b]">
			{/* Neon cosmic background */}
			<div className="fixed inset-0 -z-10 overflow-hidden bg-[#05000b]">
				{/* Deep base gradient */}
				<div className="absolute inset-0 bg-gradient-to-br from-[#0b0018] via-[#090013] to-[#020008]" />

				{/* Radial glow zones */}
				<div className="absolute inset-0 bg-[radial-gradient(circle_at_20%_25%,rgba(255,66,166,0.35),transparent_40%),radial-gradient(circle_at_80%_25%,rgba(255,130,230,0.32),transparent_45%),radial-gradient(circle_at_50%_78%,rgba(120,0,90,0.22),transparent_55%),radial-gradient(circle_at_70%_70%,rgba(255,30,140,0.2),transparent_55%)]" />

				{/* Sweeping light streaks */}
				<div className="absolute inset-0 opacity-80 bg-[linear-gradient(120deg,rgba(255,52,160,0.4),rgba(255,52,160,0)_38%),linear-gradient(-115deg,rgba(255,105,200,0.34),rgba(255,105,200,0)_32%),linear-gradient(150deg,rgba(255,90,170,0.28),rgba(255,90,170,0)_42%)]" />

				{/* Bold neon streaks */}
				<div className="absolute inset-0 pointer-events-none">
					<div className="absolute -left-28 top-10 w-[150%] h-[4px] bg-gradient-to-r from-transparent via-[#ff5bd9] to-transparent blur-[14px] rotate-[10deg] opacity-80" />
					<div className="absolute -right-16 top-1/3 w-[130%] h-[4px] bg-gradient-to-r from-transparent via-[#ff3ea7] to-transparent blur-[12px] -rotate-[14deg] opacity-68" />
					<div className="absolute left-12 bottom-1/4 w-[140%] h-[5px] bg-gradient-to-r from-transparent via-[#ff6ad5] to-transparent blur-[16px] rotate-[18deg] opacity-62" />
				</div>

				{/* Particle sparkle layer */}
				<div className="absolute inset-0 opacity-[0.06] bg-[url('data:image/svg+xml;base64,')]" />
			</div>

			{/* Main Content */}
			<div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 sm:py-16 lg:py-24">
				{/* Hero Section */}
				<motion.div
					initial={{ opacity: 0, y: 20 }}
					animate={{ opacity: 1, y: 0 }}
					transition={{ duration: 0.6 }}
					className="text-center mb-16 sm:mb-20"
				>
					{/* Badge */}
					<motion.div
						initial={{ opacity: 0, y: 10 }}
						animate={{ opacity: 1, y: 0 }}
						transition={{ delay: 0.2, duration: 0.5 }}
						className="mb-6"
					>
					<Badge 
						color="purple" 
							variant="soft" 
							size="2"
							className="inline-flex items-center gap-2 bg-pink-500/20 border-pink-500/30 !bg-pink-500/20"
						>
							<svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
								<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
							</svg>
							<span className="text-white">Introducing Channel DNA Analyzer</span>
						</Badge>
					</motion.div>

					{/* Main Headline */}
					<motion.div
						initial={{ opacity: 0, y: 20 }}
						animate={{ opacity: 1, y: 0 }}
						transition={{ delay: 0.3, duration: 0.6 }}
						className="mb-6"
					>
						<h1 className="text-[3rem] sm:text-[3.6rem] lg:text-[4.4rem] font-bold mb-4 text-white leading-tight tracking-tight">
							Reverse-Engineer What Makes{" "}
								<span
									className="inline-block"
									style={{
										backgroundImage: "linear-gradient(90deg, #ff5abf 0%, #ff3ea7 45%, #d742ff 80%, #ff8bf5 100%)",
										backgroundClip: "text",
										WebkitBackgroundClip: "text",
										WebkitTextFillColor: "transparent",
										color: "#ff5abf",
									}}
								>
								YouTube Channels Win
							</span>
						</h1>
					</motion.div>

					{/* Subtitle */}
					<motion.div
						initial={{ opacity: 0, y: 20 }}
						animate={{ opacity: 1, y: 0 }}
						transition={{ delay: 0.4, duration: 0.6 }}
						className="mb-12"
					>
						<Text size="3" className="text-white max-w-3xl mx-auto">
							Analyze posting patterns, titles, thumbnails, and content strategy — instantly.
						</Text>
					</motion.div>

					{/* Input Section */}
					<motion.div
						initial={{ opacity: 0, y: 20 }}
						animate={{ opacity: 1, y: 0 }}
						transition={{ delay: 0.5, duration: 0.6 }}
						className="max-w-3xl mx-auto"
					>
						<div className="relative p-[2px] mb-2 rounded-2xl bg-gradient-to-r from-pink-500/50 via-pink-400/20 to-pink-500/50 shadow-[0_0_35px_rgba(255,60,160,0.3)] backdrop-blur-md">
							<div className="relative rounded-[14px] bg-[#0a0013]/90 px-4 py-4 pl-12 pr-4 shadow-[inset_0_0_18px_rgba(0,0,0,0.65)] border border-pink-500/10 flex flex-col gap-2">
								{/* Icon on far left */}
								<div className="absolute left-4 top-4 text-pink-200">
									<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
										<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1" />
									</svg>
								</div>

								<div className="flex flex-col sm:flex-row sm:items-center gap-3 sm:gap-4">
									<input
										type="url"
										value={channelUrl}
										onChange={(e) => setChannelUrl(e.target.value)}
										onKeyDown={(e) => {
											if (e.key === "Enter") {
												handleAnalyze();
											}
										}}
										placeholder="Paste your YouTube URL here... (e.g., youtube.com/@channelname)"
										className="w-full bg-transparent !bg-transparent appearance-none border-0 text-sm sm:text-base text-white placeholder:text-white/70 focus:outline-none focus:text-white focus:bg-transparent transition-colors pl-8 sm:pl-10"
										style={{
											backgroundColor: "transparent",
											color: "#ffffff",
											WebkitTextFillColor: "#ffffff",
											caretColor: "#ffffff",
										}}
										autoComplete="off"
									/>

									<button
										onClick={handleAnalyze}
										className="px-5 py-2 rounded-lg text-white text-sm font-semibold hover:scale-[1.02] active:scale-[0.98] transition-transform disabled:opacity-60 disabled:cursor-not-allowed bg-transparent"
										disabled={loading}
									>
										{loading ? "Analyzing..." : "Start Analyzing"}
										<span className="ml-1 text-lg">›</span>
									</button>
								</div>

								<Text
									size="1"
									className="text-white text-[10px] sm:text-[11px] pl-8 sm:pl-10"
								>
									Example: youtube.com/@channelname
								</Text>
							</div>
						</div>
						{error && (
							<div className="text-center mt-1">
								<Text size="2" className="text-red-400">{error}</Text>
							</div>
						)}
						{analysisReady && (
							<motion.div
								initial={{ opacity: 0, y: 8 }}
								animate={{ opacity: 1, y: 0 }}
								className="mt-4 rounded-2xl bg-[#0a0013]/80 border border-pink-500/20 p-4 shadow-[0_0_20px_rgba(255,60,160,0.25)]"
							>
								<div className="flex items-center justify-between flex-wrap gap-3 mb-4">
									<Text size="3" className="text-white font-semibold">Analysis ready</Text>
									<Text size="2" className="text-white/70">Tap a tab to view details.</Text>
								</div>

								{/* Tabs */}
								<div className="flex flex-wrap gap-2 mb-4">
									{[
										"Channel DNA",
										"Growth Velocity",
										"Viral Mechanics",
										"Hooks",
										"Thumbnails",
										"Engagement",
										"SEO",
										"Publishing",
										"Portfolio",
										"Blueprint",
									].map((tab) => {
										const isActive = activeTab === tab;
										return (
											<button
												key={tab}
												onClick={() => setActiveTab(tab)}
												className={`px-3 py-2 text-sm rounded-lg border transition-colors ${
													isActive
														? "border-pink-400 bg-pink-500/20 text-white"
														: "border-white/10 bg-white/5 text-white/70 hover:border-pink-300/60 hover:text-white"
												}`}
											>
												{tab}
											</button>
										);
									})}
								</div>

								{/* Tab content */}
								<div className="rounded-xl bg-white/5 border border-white/5 p-4 text-white">
									{renderTabContent(activeTab, analysisResult, analysisData)}
								</div>
							</motion.div>
						)}
					</motion.div>
				</motion.div>

				{/* Bottom brand mark */}
				<motion.div
					initial={{ opacity: 0, y: 10 }}
					animate={{ opacity: 1, y: 0 }}
					transition={{ delay: 0.6, duration: 0.6 }}
					className="mt-10 text-center"
				>
					<Text size="5" className="text-white font-bold tracking-tight">
						CreatorOS
					</Text>
				</motion.div>

			</div>
		</div>
	);
}

function renderTabContent(tab: string, analysis: any, data: any) {
	const summary = (analysis && analysis.summary) || "—";
	const positioning = analysis?.channelPositioning || {};
	const top = analysis?.topPerformingContent || {};
	const titleStrategy = analysis?.titleStrategy || {};
	const thumb = analysis?.thumbnailStrategy || {};
	const posting = analysis?.postingStrategy || {};
	const contentLen = analysis?.contentLengthStrategy || {};
	const audience = analysis?.audienceTargeting || {};
	const takeaways = analysis?.takeaways || [];

	switch (tab) {
		case "Channel DNA":
			return (
				<div className="space-y-2 text-sm text-white/80">
					<Text size="3" className="text-white mb-2">Core Positioning</Text>
					<div>Niche: {positioning.niche || "—"}</div>
					<div>Target Audience: {positioning.targetAudience || "—"}</div>
					<div>Unique Value: {positioning.uniqueValue || "—"}</div>
					<div className="pt-2 text-white">Summary: {summary}</div>
				</div>
			);
		case "Growth Velocity":
			return (
				<div className="space-y-2 text-sm text-white/80">
					<div>Upload Frequency: {posting.frequency || data?.uploadFrequency || "—"}</div>
					<div>Consistency: {posting.consistency || "—"}</div>
					<div>Optimal Timing: {posting.optimalTiming || "—"}</div>
					<div>Recent Performance: {data?.viewCount ? `${data.viewCount} views total` : "—"}</div>
				</div>
			);
		case "Viral Mechanics":
			return (
				<div className="space-y-2 text-sm text-white/80">
					<div>Why It Works: {top.whyItWorks || "—"}</div>
					<div>Common Elements: {top.commonElements?.join(", ") || "—"}</div>
					<div>Top Content Types: {top.types?.join(", ") || "—"}</div>
				</div>
			);
		case "Hooks":
			return (
				<div className="space-y-2 text-sm text-white/80">
					<div>Title Patterns: {titleStrategy.patterns?.join(", ") || "—"}</div>
					<div>Formula: {titleStrategy.formula || "—"}</div>
				</div>
			);
		case "Thumbnails":
			return (
				<div className="space-y-2 text-sm text-white/80">
					<div>Style: {thumb.style || "—"}</div>
					<div>Best Practices: {thumb.bestPractices?.join(", ") || "—"}</div>
				</div>
			);
		case "Engagement":
			return (
				<div className="space-y-2 text-sm text-white/80">
					<div>Signals: {audience.signals?.join(", ") || "—"}</div>
					<div>Engagement Patterns: {audience.engagementPatterns || "—"}</div>
				</div>
			);
		case "SEO":
			return (
				<div className="space-y-2 text-sm text-white/80">
					<div>Keywords: {titleStrategy.keywords?.join(", ") || "—"}</div>
					<div>Length: {titleStrategy.length || "—"}</div>
				</div>
			);
		case "Publishing":
			return (
				<div className="space-y-2 text-sm text-white/80">
					<div>Cadence: {posting.frequency || "—"}</div>
					<div>Consistency: {posting.consistency || "—"}</div>
					<div>Optimal Timing: {posting.optimalTiming || "—"}</div>
				</div>
			);
		case "Portfolio":
			return (
				<div className="space-y-2 text-sm text-white/80">
					<div>Optimal Length: {contentLen.optimalLength || "—"}</div>
					<div>Format Mix: {contentLen.formatMix || "—"}</div>
					<div>Reasoning: {contentLen.reasoning || "—"}</div>
				</div>
			);
		case "Blueprint":
			return (
				<div className="space-y-2 text-sm text-white/80">
					{takeaways.length
						? takeaways.map((t: string, i: number) => <div key={i}>{i + 1}. {t}</div>)
						: "—"}
				</div>
			);
		default:
			return <div className="text-sm text-white/70">—</div>;
	}
}
